import { test, expect } from '@playwright/test';

test.describe('Password Mismatch Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="passwordForm">
        <div>
          <label for="password">Password:</label>
          <input type="password" id="password" name="password" />
        </div>
        <div>
          <label for="confirmPassword">Confirm Password:</label>
          <input type="password" id="confirmPassword" name="confirmPassword" />
        </div>
        <div id="errorMessage" style="color: red; display: none;"></div>
        <button type="submit">Submit</button>
      </form>
      <script>
        const passwordInput = document.getElementById('password');
        const confirmPasswordInput = document.getElementById('confirmPassword');
        const errorMessage = document.getElementById('errorMessage');

        function validatePasswords() {
          if (passwordInput.value && confirmPasswordInput.value && passwordInput.value !== confirmPasswordInput.value) {
            errorMessage.textContent = 'Passwords do not match';
            errorMessage.style.display = 'block';
          } else {
            errorMessage.style.display = 'none';
            errorMessage.textContent = '';
          }
        }

        passwordInput.addEventListener('input', validatePasswords);
        confirmPasswordInput.addEventListener('input', validatePasswords);
      </script>
    `);
  });

  test('should display password mismatch error when passwords do not match', async ({ page }) => {
    const passwordInput = page.getByLabel('Password:');
    const confirmPasswordInput = page.getByLabel('Confirm Password:');
    const errorMessage = page.locator('#errorMessage');

    await passwordInput.fill('MyPassword123');
    await confirmPasswordInput.fill('DifferentPassword456');

    await expect(errorMessage).toContainText('Passwords do not match');
    await expect(errorMessage).toBeVisible();
  });

  test('should hide error message when passwords match', async ({ page }) => {
    const passwordInput = page.getByLabel('Password:');
    const confirmPasswordInput = page.getByLabel('Confirm Password:');
    const errorMessage = page.locator('#errorMessage');

    await passwordInput.fill('MyPassword123');
    await confirmPasswordInput.fill('DifferentPassword456');
    await expect(errorMessage).toBeVisible();

    await confirmPasswordInput.fill('MyPassword123');
    await expect(errorMessage).not.toBeVisible();
  });

  test('should not display error when confirm password field is empty', async ({ page }) => {
    const passwordInput = page.getByLabel('Password:');
    const confirmPasswordInput = page.getByLabel('Confirm Password:');
    const errorMessage = page.locator('#errorMessage');

    await passwordInput.fill('MyPassword123');
    await expect(errorMessage).not.toBeVisible();
  });

  test('should clear error message when password field is cleared', async ({ page }) => {
    const passwordInput = page.getByLabel('Password:');
    const confirmPasswordInput = page.getByLabel('Confirm Password:');
    const errorMessage = page.locator('#errorMessage');

    await passwordInput.fill('MyPassword123');
    await confirmPasswordInput.fill('DifferentPassword456');
    await expect(errorMessage).toBeVisible();

    await passwordInput.clear();
    await expect(errorMessage).not.toBeVisible();
  });
});
